ReentrantReadWriteLock rwl = new ReentrantReadWriteLock();
ReadLock readLock = rwl.readLock();
WriteLock writeLock = rwl.writeLock();

// ═══ READ: multiple concurrent readers ═══
readLock.lock();
try {
    return balance;  // 100 threads can be here simultaneously!
} finally { readLock.unlock(); }

// ═══ WRITE: exclusive — blocks all readers ═══
writeLock.lock();
try {
    balance = balance.subtract(amount);  // only ONE thread here!
    // All readers blocked until this write finishes!
} finally { writeLock.unlock(); }

// ═══ WHEN IT HELPS: read-heavy (95% reads, 5% writes) ═══
// ReentrantLock: 100 reads/sec → sequential → 100ms total
// ReadWriteLock: 100 reads/sec → parallel → ~1ms total! 100x faster!
// Writes are rare → readers rarely blocked

// ═══ WHEN IT HURTS: write-heavy (50% writes) ═══
// Every write: acquires writeLock → blocks ALL readers → CAS overhead
// Reader count: shared AtomicInteger → CAS contention between readers!
// ReentrantLock: simpler, less overhead, no reader-count CAS
// ReadWriteLock: more complex, more overhead, net SLOWER!

// ═══ WRITE-TO-READ DOWNGRADE (allowed!) ═══
writeLock.lock();
try {
    updateData();
    readLock.lock();    // acquire read WHILE holding write!
} finally { writeLock.unlock(); }  // release write → now hold only read!
try { return data; }
finally { readLock.unlock(); }

// ═══ READ-TO-WRITE UPGRADE (NOT allowed!) ═══
// readLock.lock();
// writeLock.lock();  // DEADLOCK! Can't upgrade!
// Must: unlock read → lock write (but another thread may write between!)

// ═══ FAIRNESS ═══
ReentrantReadWriteLock fair = new ReentrantReadWriteLock(true);
// Fair: longest-waiting thread gets lock next (FIFO)
// Non-fair (default): barging allowed — faster but readers can starve writers!
