package com.bank.rwl;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;
import static org.assertj.core.api.Assertions.*;

class ReadWriteLockTest {

    // ═══ Multiple concurrent readers ═══
    @Test
    void multipleReaders_concurrent() throws InterruptedException {
        ReentrantReadWriteLock rwl = new ReentrantReadWriteLock();
        int[] balance = {100000};
        int readers = 10;
        CountDownLatch allReading = new CountDownLatch(readers);
        CountDownLatch canFinish = new CountDownLatch(1);

        for (int i = 0; i < readers; i++) {
            new Thread(() -> {
                rwl.readLock().lock();
                try {
                    allReading.countDown();
                    try { canFinish.await(5, TimeUnit.SECONDS); } catch (InterruptedException e) { }
                    int b = balance[0];
                } finally { rwl.readLock().unlock(); }
            }).start();
        }

        allReading.await(5, TimeUnit.SECONDS);
        assertThat(rwl.getReadLockCount()).isEqualTo(readers);  // ALL 10 reading!
        canFinish.countDown();
    }

    // ═══ Writer blocks readers ═══
    @Test
    void writer_blocksReaders() throws InterruptedException {
        ReentrantReadWriteLock rwl = new ReentrantReadWriteLock();
        int[] balance = {100000};
        CountDownLatch writeHeld = new CountDownLatch(1);

        Thread writer = new Thread(() -> {
            rwl.writeLock().lock();
            try {
                writeHeld.countDown();
                Thread.sleep(300);
                balance[0] = 50000;
            } catch (InterruptedException e) { }
            finally { rwl.writeLock().unlock(); }
        });
        writer.start();
        writeHeld.await();

        // Reader tries while writer holds → BLOCKED!
        long start = System.currentTimeMillis();
        rwl.readLock().lock();
        try {
            long elapsed = System.currentTimeMillis() - start;
            assertThat(elapsed).isGreaterThanOrEqualTo(200);  // was blocked!
            assertThat(balance[0]).isEqualTo(50000);  // sees writer's update!
        } finally { rwl.readLock().unlock(); }
        writer.join();
    }

    // ═══ Read-heavy performance: RWL vs ReentrantLock ═══
    @Test
    void readHeavy_rwlFaster() throws InterruptedException {
        int[] data = {42};
        int readers = 20;
        int iterations = 100_000;

        // ReadWriteLock:
        ReentrantReadWriteLock rwl = new ReentrantReadWriteLock();
        long rwlTime = benchmarkReads(data, readers, iterations, () -> rwl.readLock().lock(), () -> rwl.readLock().unlock());

        // ReentrantLock:
        ReentrantLock rl = new ReentrantLock();
        long rlTime = benchmarkReads(data, readers, iterations, rl::lock, rl::unlock);

        System.out.println("ReadWriteLock: " + rwlTime + "ms, ReentrantLock: " + rlTime + "ms");
        // RWL should be faster for read-heavy!
    }

    long benchmarkReads(int[] data, int readers, int iterations, Runnable lock, Runnable unlock) throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(readers);
        long start = System.currentTimeMillis();

        for (int r = 0; r < readers; r++) {
            new Thread(() -> {
                for (int i = 0; i < iterations; i++) {
                    lock.run();
                    try { int x = data[0]; }
                    finally { unlock.run(); }
                }
                latch.countDown();
            }).start();
        }
        latch.await();
        return System.currentTimeMillis() - start;
    }
}
